import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 공유 권한 보유자는 문서 작성자 또는 수정 권한을 받은 공유 대상자이다.
// 가정: 공유 대상(그룹웨어 사용자)은 재직 중인 직원이다.
// 가정: 쪽지는 messenger_message에 NOTE로 저장한다. 이메일은 대상자의 이메일 주소가 있어야 발송 요청을 접수한다.
const SHARE_METHODS = ['NOTE', 'EMAIL'];

interface Target {
  employeeId: string;
  canEdit: boolean;
}

@Controller('api/v1')
export class FnSfr04105Controller {
  @Post('/office-documents/:officeDocumentId/share')
  @HttpCode(200)
  async shareOfficeDocument(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const documentId = String(req.params['officeDocumentId']);
    if (!/^\d+$/.test(documentId)) {
      throw new ApiError(404, 'OFFICE_DOCUMENT_NOT_FOUND', '공유할 문서를 찾을 수 없습니다.');
    }
    const shareMethod = data['shareMethod'];
    if (typeof shareMethod !== 'string' || !SHARE_METHODS.includes(shareMethod)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '공유 방식은 쪽지 또는 이메일로 선택해 주세요.');
    }
    const rawTargets = data['targets'];
    if (!Array.isArray(rawTargets) || rawTargets.length === 0) {
      throw new ApiError(422, 'SHARE_TARGET_REQUIRED', '공유 대상자와 권한을 지정해 주세요.');
    }
    const targets: Target[] = [];
    for (const raw of rawTargets) {
      const item = raw as Record<string, unknown> | null;
      if (item === null || typeof item !== 'object') {
        throw new ApiError(422, 'SHARE_TARGET_REQUIRED', '공유 대상자와 권한을 지정해 주세요.');
      }
      const employeeId = String(item['employeeId'] ?? '');
      if (!/^\d+$/.test(employeeId) || typeof item['canEdit'] !== 'boolean') {
        throw new ApiError(422, 'SHARE_TARGET_REQUIRED', '공유 대상자와 권한을 지정해 주세요.');
      }
      targets.push({ employeeId, canEdit: item['canEdit'] });
    }

    return transaction(async (db) => {
      const docs = await db.query(
        `SELECT d.title AS "title",
                (d.author_id = CAST(:userId AS bigint)
                 OR EXISTS (SELECT 1 FROM office_document_share s
                            WHERE s.office_document_id = d.office_document_id
                              AND s.employee_id = CAST(:userId AS bigint)
                              AND s.can_edit = true)) AS "canShare"
           FROM office_document d
          WHERE d.office_document_id = CAST(:documentId AS bigint)`,
        { documentId, userId: user.id },
      );
      if (docs.length === 0) {
        throw new ApiError(404, 'OFFICE_DOCUMENT_NOT_FOUND', '공유할 문서를 찾을 수 없습니다.');
      }
      if (docs[0]['canShare'] !== true) {
        throw new ApiError(403, 'FORBIDDEN', '이 문서를 공유할 권한이 없습니다.');
      }

      for (const target of targets) {
        const employees = await db.query(
          `SELECT email AS "email"
             FROM employee
            WHERE employee_id = CAST(:employeeId AS bigint)
              AND employment_status = '재직자'`,
          { employeeId: target.employeeId },
        );
        if (employees.length === 0) {
          throw new ApiError(422, 'INVALID_SHARE_PERMISSION', '그룹웨어 사용자가 아닌 대상자는 지정할 수 없습니다.');
        }
        if (shareMethod === 'EMAIL' && !employees[0]['email']) {
          throw new ApiError(502, 'SHARE_NOTIFICATION_FAILED', '이메일 주소가 없는 대상자에게는 안내를 발송할 수 없습니다.');
        }
        // 열람 권한은 공유 행의 존재로 부여되므로 수정 권한은 항상 열람 권한을 전제로 한다.
        await db.execute(
          `INSERT INTO office_document_share
             (office_document_id, employee_id, can_edit, created_at, updated_at)
           VALUES (CAST(:documentId AS bigint), CAST(:employeeId AS bigint), :canEdit, now(), now())
           ON CONFLICT (office_document_id, employee_id)
           DO UPDATE SET can_edit = EXCLUDED.can_edit, updated_at = now()`,
          { documentId, employeeId: target.employeeId, canEdit: target.canEdit },
        );
      }

      let notificationStatus = 'EMAIL_REQUESTED';
      if (shareMethod === 'NOTE') {
        const content = '문서 공유 안내: ' + String(docs[0]['title']);
        await db.query(
          `INSERT INTO messenger_message
             (sender_id, message_type, content, sent_at, created_at, updated_at)
           VALUES (CAST(:userId AS bigint), 'NOTE', :content, now(), now(), now())
           RETURNING messenger_message_id AS "messengerMessageId"`,
          { userId: user.id, content },
        );
        notificationStatus = 'NOTE_SENT';
      }

      const granted = await db.query(
        `SELECT employee_id AS "employeeId", can_edit AS "canEdit"
           FROM office_document_share
          WHERE office_document_id = CAST(:documentId AS bigint)
          ORDER BY office_document_share_id`,
        { documentId },
      );
      return { shared: true, grantedPermissions: granted, notificationStatus };
    });
  }
}

