import { useState } from 'react';
import { Band, Badge, DataTable, Drawer, Field, Form, LookupSelect, RefName, Select, call } from '../kit';
import type { PageProps, Row } from '../kit';

interface TargetInput {
  employeeId: number | string;
  canEdit: string;
}

const METHODS: [string, string][] = [
  ['NOTE', '쪽지'],
  ['EMAIL', '이메일'],
];

const PERMISSIONS: [string, string][] = [
  ['false', '열람'],
  ['true', '열람·수정'],
];

export default function FnSfr04105Page({ role, notify }: PageProps) {
  const [results, setResults] = useState<Row[]>([]);
  const [open, setOpen] = useState(false);
  const [documentId, setDocumentId] = useState<number | string>('');
  const [shareMethod, setShareMethod] = useState('NOTE');
  const [targets, setTargets] = useState<TargetInput[]>([{ employeeId: '', canEdit: 'false' }]);

  function openDrawer() {
    setDocumentId('');
    setShareMethod('NOTE');
    setTargets([{ employeeId: '', canEdit: 'false' }]);
    setOpen(true);
  }

  function changeTarget(index: number, patch: Partial<TargetInput>) {
    setTargets(targets.map((t, i) => (i === index ? { ...t, ...patch } : t)));
  }

  async function submit() {
    if (documentId === '') {
      throw new Error('공유할 문서를 선택해 주세요.');
    }
    if (targets.length === 0 || targets.some((t) => t.employeeId === '')) {
      throw new Error('공유 대상자와 권한을 지정해 주세요.');
    }
    const res = await call('POST', '/office-documents/' + documentId + '/share', role, {
      shareMethod,
      targets: targets.map((t) => ({ employeeId: t.employeeId, canEdit: t.canEdit === 'true' })),
    });
    setResults([{ ...res, id: results.length + 1, officeDocumentId: documentId, shareMethod }, ...results]);
    setOpen(false);
    notify('문서를 공유했습니다.');
  }

  return (
    <div className="doc">
      <section className="box">
        <h2>문서 공유</h2>
        <Band total={results.length}>
          <button onClick={openDrawer}>문서 공유</button>
        </Band>
        <DataTable
          rows={results}
          empty="아직 공유한 문서가 없습니다. 문서 공유 버튼을 눌러 시작해 주세요."
          columns={[
            { key: 'officeDocumentId', label: '문서', render: (r) => <RefName table="office_document" role={role} value={r['officeDocumentId']} /> },
            { key: 'shareMethod', label: '공유 방식', render: (r) => (r['shareMethod'] === 'EMAIL' ? '이메일' : '쪽지') },
            {
              key: 'grantedPermissions',
              label: '대상자별 권한',
              render: (r) => (
                <div>
                  {((r['grantedPermissions'] as Row[]) ?? []).map((g, i) => (
                    <div key={i}>
                      <RefName table="employee" role={role} value={g['employeeId']} />
                      {g['canEdit'] === true ? ' · 열람·수정' : ' · 열람'}
                    </div>
                  ))}
                </div>
              ),
            },
            { key: 'notificationStatus', label: '안내 발송 결과', render: (r) => <Badge value={r['notificationStatus']} /> },
          ]}
        />
      </section>
      {open && (
        <Drawer title="문서 공유" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="공유">
            <Field label="공유할 문서" required wide>
              <LookupSelect table="office_document" role={role} value={documentId} onChange={setDocumentId} placeholder="문서 선택" />
            </Field>
            <Field label="공유 방식 (쪽지 또는 이메일)" required wide>
              <Select value={shareMethod} onChange={setShareMethod} options={METHODS} />
            </Field>
            {targets.map((t, i) => (
              <Field key={i} label={'공유 대상자 ' + (i + 1)} required wide hint="열람 권한은 공유와 함께 부여되며, 수정 권한은 열람 권한을 포함합니다.">
                <LookupSelect table="employee" role={role} value={t.employeeId} onChange={(v) => changeTarget(i, { employeeId: v })} placeholder="대상자 선택" />
                <Select value={t.canEdit} onChange={(v) => changeTarget(i, { canEdit: v })} options={PERMISSIONS} placeholder="권한 선택" />
                {targets.length > 1 && (
                  <button type="button" className="ghost" onClick={() => setTargets(targets.filter((_, j) => j !== i))}>
                    대상자 삭제
                  </button>
                )}
              </Field>
            ))}
            <button type="button" className="ghost" onClick={() => setTargets([...targets, { employeeId: '', canEdit: 'false' }])}>
              대상자 추가
            </button>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
